class Solution { public:
    vector<vector<int>> mergeSimilarItems(vector<vector<int>>& items1,vector<vector<int>>& items2) {
        map<int,int> sum;for(auto &v:items1)sum[v[0]]+=v[1];for(auto &v:items2)sum[v[0]]+=v[1];
        vector<vector<int>> ans;for(auto &p:sum)ans.push_back({p.first,p.second});return ans;
    }
};
